			Type = "Survival" 
		},
		Vor = {
			Alias = "Vor",
			InternalName = "/Lotus/Types/Game/MissionDecks/BossMissionRewards/SeerPistolRewards",
			Link = "Captain Vor",
			Name = "Captain Vor Assassination",
			Rewards = {
				A = {
					{ "Seer Blueprint", "Blueprint", 38.72 },
					{ "Seer Barrel", "Blueprint", 38.72 },
					{ "Seer Receiver", "Blueprint", 22.56 },
				},
			},
			Tier = "Vor",
			Type = "Assassinate" 
		}
	},
	Rewards = {},
}
-- TODO: This data should just be in the data by default instead of generated since we
-- will eventually bump into issues with weapons that share similar suffixes. For example,
-- if DE releases a weapon named Dorma, then it will conflict with Forma entries.
local validTypes = { Blueprint = true, Component = true, Arcane = true, }
-- Any reward names that start with these strings are not found in Missions tables
-- Only include weapons with parts (i.e. 'Broken War' and 'Twin Kohmak' can be safely omitted)
local outliers = {
	rvius = true, -- Orvius is categorized in 'resources'
	ctavia = true, -- ?
	rcane = true,rimary = true,econdary = true,mergence = true,ascadia = true,ternal = true,ractalized = true,olt = true,-- Arcanes are categorized in 'mods'
	orma = true, -- built forma is categorized in 'resources'
	ildryn = true, -- Hildryn is dropped by an enemy
	orgon = true, -- Gorgon is dropped by an enemy
	etron = true, -- Detron is dropped by an enemy
	antis = true, -- Mantis is dropped by containers
	cimitar = true, -- Scimitar is dropped by enemies
	karius = true, -- Akarius is dropped by enemies
	cceltra = true, -- Acceltra is dropped by enemies
	olf = true, -- Wolf sledge is dropped by an enemy
	ar = true,	-- War parts are dropped by an enemy
	-- ['roken War'] = true,	-- Broken War parts is dropped by enemies
	roken = true,	-- Broken War
	oar = true,	-- Boar bp is dropped by enemies
	ronus = true,	-- Cronus
	read = true,	-- Dread
	espair = true,	-- Despair
	ate = true,	-- Hate
	rakk = true,	-- Brakk
	orrudo = true,	--Korrudo
	-- ['win Kohmak'] = true,	-- Twin Kohmak
	win = true,	-- Twin Kohmak
	uellor = true,	-- Quellor
	hedu = true,	-- Shedu
	ennant = true,	-- Pennant
	espar = true,	-- Hespar
	eolak = true,	-- Aeolak
	lternox = true,	-- Alternox
	erigale = true,	-- Perigale
	arofang = true,	-- Sarofang
}
local modSources = {--things that drop arcanes in their "Mods" pool
	Angst = true,
	Malice = true,
	Mania = true,
	Misery = true,
	Torment = true,
	Violence = true,
	['Thrax Centurion'] = true,
	['Thrax Legatus'] = true,
	['Void Angel'] = true,
	['Ravenous Void Angel'] = true,
	-- or sk:find'^Eidolon'
	['Eidolon Teralyst Capture'] = true,
	['Eidolon Teralyst Kill'] = true,
	['Eidolon Gantulyst Capture'] = true,
	['Eidolon Gantulyst Kill'] = true,
	['Eidolon Hydrolyst Capture'] = true,
	['Eidolon Hydrolyst Kill'] = true,
	['Mocking Whisper'] = true,
	['Scathing Whisper'] = true,
	['Sisters of Parvos (Ascension Mode)'] = true,
	['Sisters of Parvos (Ascension Hard Mode)'] = true,
	['H-09 Efervon Tank'] = true,
	['Scaldra Screamer'] = true,
}

for category, sources in pairs(DropData) do
	for sk, source in pairs(sources) do
		if (not source._IgnoreEntry) then
			local t = {}
			if source.Rewards then
				t.A = source.Rewards.A
				t.B = source.Rewards.B
				t.C = source.Rewards.C
			end
			t.Mods = modSources[sk] and source.Mods
			t.Resources = source.Resources
			t.Blueprints = source.Blueprints
			t.Items = source.Items
			for rk, rewardPool in pairs(t) do
				for i, reward in ipairs(rewardPool) do
					if type(reward[1]) == 'string' and outliers[reward[1]:match'^.(%a+)'] or validTypes[reward[2]] then
						DropData.Rewards[reward[1]] = DropData.Rewards[reward[1]] or {}
						table.insert(DropData.Rewards[reward[1]], {
							Probability = reward[#reward] * (source[rk:sub(1, -2)..'Chance'] or 100) / 10000,
							Source = source,
							Entry = reward,
							category, sk, rk, i
						})
					end
				end
			end
		end
	end
end

return DropData